+/// Case-insensitive header lookup (header casing varies by hop).
+String? _header(Map<String, String> headers, String name) {
+  for (final entry in headers.entries) {
+    if (entry.key.toLowerCase() == name) return entry.value.trim();
+  }
+  return null;
+}
