    model: model.id,
    responseModel: responseModel,
    responseId: responseId,
    usage: usage,
    stopReason: stopReason,
    rawStopReason: rawStopReason,
    errorMessage: errorMessage,
    rateLimit: rateLimit,
    timestamp: timestamp,
  );
}

