+  final resetsAt = DateTime.utc(2026, 10, 19, 19, 49, 31);
+  const rawPayload =
+      '{"error":{"type":"usage_limit_reached","plan_type":"free",'
+      '"resets_at":1792439371,"resets_in_seconds":2280562}}';
