/// (`Wed, 21 Oct 2015 07:28:00 GMT`). Returns `null` for anything else.
DateTime? _parseHttpDate(String value) {
  final match = _httpDatePattern.firstMatch(value);
  if (match == null) {
    return null;
  }
  final month = _httpMonths[match[2]!.toLowerCase()];
  if (month == null) {
    return null;
  }
  return DateTime.utc(
    int.parse(match[3]!),
    month,
    int.parse(match[1]!),
    int.parse(match[4]!),
    int.parse(match[5]!),
    int.parse(match[6]!),
  );
}

