+  /// Creates the info; [rawBody] keeps the full payload for diagnostics.
+  const RateLimitInfo({
+    this.errorType,
+    this.planType,
+    this.resetsAt,
+    this.resetsInSeconds,
+    this.eligiblePromo,
+    this.limitKind,
+    this.retryAfter,
+    this.rawBody = '',
+  });
