  // must SEE instead of an empty assistant message.
  if (contentTypeLower.contains('application/json')) {
    final body = await response.stream.bytesToString();
    throw ProviderHttpError(
      200,
      body,
      requestUrl: request.url,
      answeredJson: true,
    );
  }
  return response;
